// Lists and reports as formal A4 documents on the letterhead (docs/A4_PDF_PROMPT.md stage 2):
//   * corner: the report name and the period (or "As of <date>" for current-state lists);
//   * page 1: seller line, office, period, filters, "Generated by … on …";
//   * the table with its header on every page, rows never split, figures right-aligned, a totals
//     row once at the end, "No rows" when empty;
//   * "<report> · Page x of y" at the bottom of every page.
// Wide tables (decision 2): portrait, with the type reduced (not below 6.5 pt) and text wrapped so
// the columns fit; only above 10 columns landscape A4 with a drawn header and footer.
// Loaded on demand from src/utils/export.ts (jsPDF stays out of the initial bundle).
import { printDate } from '../invoicePrint';
import type { DocumentCompany, DocumentOffice } from '../branding';
import {
  INK, LAYOUT, MUTED, RULE, a4Table, bodyWidth, factsBlock, loadLetterheadBytes, sellerBlock, startA4, stampPages,
  textBlock, LANDSCAPE, PORTRAIT, type A4, type Doc, type Rgb,
} from './frame';

export type ReportPeriod = { from?: string; to?: string } | { asOf: string };

export interface TableReport {
  /** File stem, e.g. "Vehicle_Master_Report". */
  name: string;
  /** Shown top right and in the page label, e.g. "Vehicle Master Report". */
  title: string;
  columns: string[];
  rows: string[][];
  /** Column indexes holding figures (right-aligned, never wrapped). */
  rightAlign?: number[];
  /** A totals row printed once after the last row. */
  totals?: string[];
  /** One extra line under the seller line. */
  subtitle?: string;
  /** Filters the rows were produced with; empty values are left out. */
  filters?: [string, string][];
  /** The office the rows belong to; null = All offices. */
  office: DocumentOffice | null;
  /** Dated reports: the period; current-state lists: as of a date (default today). */
  period?: ReportPeriod;
  company: DocumentCompany;
  generatedBy?: string;
  now?: Date;
}

/** Above this many columns a table is printed landscape (decision 2). */
export const LANDSCAPE_ABOVE = 10;
export const MIN_FONT = 6.5;

const ymd = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const hm = (d: Date) => `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;

/** Corner text: "01-Jan-2026 to 15-Nov-2026", "From 01-Jan-2026", "Up to 15-Nov-2026" or "As of 15-Nov-2026". */
export function periodText(period: ReportPeriod | undefined, today: string): string {
  if (period && 'asOf' in period) return `As of ${printDate(period.asOf)}`;
  const from = period?.from, to = period?.to;
  if (from && to) return `${printDate(from)} to ${printDate(to)}`;
  if (from) return `From ${printDate(from)}`;
  if (to) return `Up to ${printDate(to)}`;
  return `As of ${printDate(today)}`;
}

const safe = (s: string) => s.replace(/[^A-Za-z0-9_-]+/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '');

/**
 * `<Report>_<office code or All>_<from>_<to>.pdf` for a period, `<Report>_<office>_<date>.pdf`
 * otherwise (docs/A4_PDF_PROMPT.md B3).
 */
export function reportFileName(name: string, office: Pick<DocumentOffice, 'code'> | null, period: ReportPeriod | undefined, today: string): string {
  const parts = [safe(name) || 'Report', safe(office?.code ?? '') || 'All'];
  if (period && 'asOf' in period) parts.push(period.asOf);
  else if (period?.from || period?.to) parts.push(...[period.from, period.to].filter((x): x is string => !!x));
  else parts.push(today);
  return `${parts.join('_')}.pdf`;
}

/** The landscape footer: company details from Settings, empty parts left out. */
export function footerLine(c: DocumentCompany): string {
  const place = [c.address, c.city, c.country].filter(Boolean).join(', ');
  return [c.legalName, c.crNumber && `CR ${c.crNumber}`, c.vatNumber && `VATIN ${c.vatNumber}`, place, c.phone && `T. ${c.phone}`, c.email]
    .filter(Boolean).join('  ·  ');
}

/**
 * How a table fits: landscape only above 10 columns; the font is reduced from the body size until the
 * columns' natural widths fit the body (text columns may wrap, so they count at most 45 mm), not below
 * 6.5 pt. Figures get a minimum width so they never wrap.
 */
export function tableLayout(doc: Doc, columns: string[], rows: string[][], rightAlign: number[] = []) {
  const g = columns.length > LANDSCAPE_ABOVE ? LANDSCAPE : PORTRAIT;
  const avail = g.body.right - g.body.left;
  const pad = 2 * 1.4;
  const base = LAYOUT.font.body;
  const widthAt = (text: string, size: number, bold = false) => {
    doc.setFont('helvetica', bold ? 'bold' : 'normal');
    doc.setFontSize(size);
    return Math.max(...text.split('\n').map(t => doc.getTextWidth(t)));
  };
  // the few longest cells of each column are enough to find its widest one
  const longest = columns.map((_, c) => rows.map(r => String(r[c] ?? '')).sort((a, b) => b.length - a.length).slice(0, 5));
  const natural = (size: number) => columns.map((h, c) => {
    const cell = Math.max(0, ...longest[c].map(t => widthAt(t, size)));
    const head = widthAt(h, size, true);
    const w = Math.max(cell, rightAlign.includes(c) ? Math.min(head, 30) : head) + pad;
    return rightAlign.includes(c) ? w : Math.min(w, 45);
  });
  const sum = natural(base).reduce((a, b) => a + b, 0);
  let fontSize: number = base;
  if (sum > avail) fontSize = Math.max(MIN_FONT, Math.floor((base * avail / sum) * 2) / 2);
  const columnStyles: Record<number, { minCellWidth: number }> = {};
  for (const c of rightAlign) {
    if (c >= columns.length) continue;
    const cell = Math.max(0, ...longest[c].map(t => widthAt(t, fontSize)));
    columnStyles[c] = { minCellWidth: Math.min(cell + pad, avail / 3) };
  }
  return { orientation: g.orientation, fontSize, columnStyles };
}

/** PNG width/height from its header, so the logo keeps its proportions. */
function pngSize(bytes: Uint8Array): { width: number; height: number } {
  const v = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return { width: v.getUint32(16), height: v.getUint32(20) };
}

export interface ReportAssets { letterhead: Uint8Array | null; logo: Uint8Array | null }

/** The letterhead (portrait) or the logo (landscape), fetched only when needed. */
export async function loadReportAssets(landscape: boolean): Promise<ReportAssets> {
  if (!landscape) return { letterhead: await loadLetterheadBytes(), logo: null };
  try {
    const { BRAND_LOGO_URL } = await import('../brandAssets');
    const res = await fetch(BRAND_LOGO_URL);
    return { letterhead: null, logo: res.ok ? new Uint8Array(await res.arrayBuffer()) : null };
  } catch {
    return { letterhead: null, logo: null };
  }
}

export const needsLandscape = (columns: number) => columns > LANDSCAPE_ABOVE;

export function buildTableReportPdf(r: TableReport, assets: ReportAssets): { doc: Doc; fileName: string } {
  const now = r.now ?? new Date();
  const today = ymd(now);
  const corner = periodText(r.period, today);
  const rightAlign = r.rightAlign ?? [];

  // measure on a scratch page of the right orientation, then draw
  const probe = startA4({ title: '', corner: '', letterhead: null, orientation: needsLandscape(r.columns.length) ? 'landscape' : 'portrait' });
  const layout = tableLayout(probe.doc, r.columns, r.rows, rightAlign);

  const a: A4 = startA4({
    title: r.title.toUpperCase(), corner, footer: r.title, letterhead: assets.letterhead, orientation: layout.orientation,
    logo: assets.logo ? { bytes: assets.logo, ...pngSize(assets.logo) } : null,
    footerLine: footerLine(r.company),
    properties: { title: `${r.title} ${corner}`, subject: r.title, author: r.company.legalName, creator: r.company.legalName },
  });
  const left = a.g.body.left;
  const width = bodyWidth(a);

  // ---- page 1 block
  let y = sellerBlock(a, {
    name: r.company.legalName,
    vat: r.office?.vatNumber || r.company.vatNumber,
    cr: r.office?.registrationNumber || r.company.crNumber,
  });
  if (r.subtitle) y = textBlock(a, [r.subtitle], left, y + 0.5, width, LAYOUT.font.body, 'bold');
  const filters = (r.filters ?? []).filter(([, v]) => v !== '' && v != null).map(([k, v]) => `${k}: ${v}`).join('   ·   ');
  const facts: Array<[string, string]> = [
    ['Office', r.office ? `${r.office.name}${r.office.code ? ` (${r.office.code})` : ''}` : 'All offices'],
    [r.period && !('asOf' in r.period) && (r.period.from || r.period.to) ? 'Period' : 'As of', corner.replace(/^As of /, '')],
    ...(filters ? [['Filters', filters] as [string, string]] : []),
    ['Generated', `${r.generatedBy ? `by ${r.generatedBy} ` : ''}on ${printDate(today)} ${hm(now)}`],
  ];
  y = factsBlock(a, facts, left, y + 2, 24, width) + 2;

  // ---- table
  const head = Math.max(MIN_FONT, layout.fontSize - 0.5);
  const none = false as unknown as Rgb;
  a4Table(a, {
    head: [r.columns],
    body: r.rows.length ? r.rows : [[{ content: 'No rows', colSpan: Math.max(r.columns.length, 1), styles: { halign: 'center', textColor: MUTED } }]],
    foot: r.totals ? [r.totals] : undefined,
    showFoot: 'lastPage',
    startY: y,
    theme: 'grid',
    styles: { fontSize: layout.fontSize, cellPadding: 1.4, lineColor: RULE, lineWidth: 0.15, valign: 'top', overflow: 'linebreak', fillColor: none },
    headStyles: { fontSize: head },
    footStyles: { fontStyle: 'bold', textColor: INK, fillColor: none, lineColor: INK, lineWidth: { top: 0.3 } },
    alternateRowStyles: { fillColor: none },
    numeric: rightAlign.filter(i => i < r.columns.length),
    columnStyles: layout.columnStyles,
    didParseCell: cell => { if (cell.section === 'foot' && rightAlign.includes(cell.column.index)) cell.cell.styles.halign = 'right'; },
  });

  stampPages(a);
  return { doc: a.doc, fileName: reportFileName(r.name, r.office, r.period, today) };
}

